package com.euvcraft.lithmod.mc.multiblock.scanner;
import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import java.util.*;
/** Fixed domain [-2,2], range [-8,8]; target is amber, last paid candidate cyan. */
public final class DiagnosticScreen extends AbstractContainerScreen<DiagnosticMenu>{
 private final List<EditBox> fields=new ArrayList<>();private Button plot,accept;private boolean initialized;
 public DiagnosticScreen(DiagnosticMenu m,Inventory i,Component t){super(m,i,t,320,300);}
 private void send(int id){if(minecraft!=null&&minecraft.gameMode!=null)minecraft.gameMode.handleInventoryButtonClick(menu.containerId,id);}
 @Override protected void init(){super.init();fields.clear();initialized=false;for(int k=0;k<3;k++){var field=new EditBox(font,leftPos+20+k*82,topPos+170,74,18,Component.literal(new String[]{"A","b","c"}[k]));field.setMaxLength(6);field.setValue("0.00");fields.add(addRenderableWidget(field));}
 plot=addRenderableWidget(Button.builder(Component.literal("Plot (1 paper)"),b->plot()).bounds(leftPos+20,topPos+191,120,20).build());accept=addRenderableWidget(Button.builder(Component.literal("Accept fit"),b->send(2001)).bounds(leftPos+151,topPos+191,115,20).build());}
 private Integer coefficient(EditBox box){try{double value=Double.parseDouble(box.getValue());if(!Double.isFinite(value)||value< -2||value>2)return null;return (int)Math.round(value*100);}catch(NumberFormatException invalid){return null;}}
 private void plot(){var v=fields.stream().map(this::coefficient).toList();if(v.contains(null))return;send(v.get(0)+200);send(v.get(1)+601);send(v.get(2)+1002);send(2000);}
 @Override protected void containerTick(){super.containerTick();if(!initialized){for(int k=0;k<3;k++)fields.get(k).setValue(String.format(Locale.ROOT,"%.2f",menu.value(3+k)/100.0));initialized=true;}boolean enabled=menu.value(0)==1&&menu.value(6)==0&&menu.value(10)==1;plot.active=enabled&&fields.stream().allMatch(f->coefficient(f)!=null)&&menu.slots.get(0).hasItem();accept.active=enabled&&menu.value(2)>=menu.value(7);for(var f:fields)f.setEditable(enabled);}
 @Override public void extractBackground(GuiGraphicsExtractor g,int mx,int my,float partial){super.extractBackground(g,mx,my,partial);g.fill(leftPos,topPos,leftPos+imageWidth,topPos+imageHeight,0xFFD0D0D0);int x=leftPos+15,y=topPos+30;g.fill(x,y,x+290,y+120,0xFF152030);g.fill(x+144,y,x+145,y+120,0xFF536070);g.fill(x,y+60,x+290,y+61,0xFF536070);
  for(int start:new int[]{11,52})for(int n=0;n<40;n++){int py=map(menu.value(start+n)),ny=map(menu.value(start+n+1));int px=x+n*289/40,nx=x+(n+1)*289/40;for(int xx=px;xx<=nx;xx++){int yy=py+(ny-py)*(xx-px)/Math.max(1,nx-px);g.fill(xx,y+yy,xx+1,y+yy+1,start==11?0xFFFFC857:0xFF53D8FB);}}
  for(var slot:menu.slots){g.fill(leftPos+slot.x-1,topPos+slot.y-1,leftPos+slot.x+17,topPos+slot.y+17,0xFF777777);g.fill(leftPos+slot.x,topPos+slot.y,leftPos+slot.x+16,topPos+slot.y+16,0xFFA0A0A0);}
 }
 private int map(int hundredths){return Math.clamp(60-hundredths*119/1600,1,118);}private void text(GuiGraphicsExtractor g,String text,int x,int y){g.text(font,font.plainSubstrByWidth(text,304-x),x,y,0xFF303030,false);}
 @Override protected void extractLabels(GuiGraphicsExtractor g,int mx,int my){text(g,"Diagnostic tuning: y = Ax² + bx + c",8,7);text(g,"Target: amber   Last plot: cyan   x: -2 to 2",15,19);text(g,"A                      b                      c    (-2.00 to 2.00)",20,157);text(g,"Paper",276,173);text(g,"Quality "+menu.value(2)+"/100  Yield ×"+menu.value(8)/1000.0+"  Min "+menu.value(7),15,302-3);text(g,menu.value(6)!=0?"Locked during processing":menu.value(1)==1?"Fit accepted":"Adjust coefficients, plot, then accept",15,211-1);}
}
